// Accepts only events Convex signed with the Convex-to-n8n secret within the last five minutes.
// The check runs on the raw body exactly as received, before anything is parsed.
const crypto = require('crypto');

const TOLERANCE_SECONDS = 300;
const item = $input.first();
const headers = item.json.headers ?? {};
const raw = item.binary?.data
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : '';
const timestamp = String(headers['x-lendloop-timestamp'] ?? '');
const given = Buffer.from(String(headers['x-lendloop-signature'] ?? '').toLowerCase(), 'utf8');
const isFresh =
  /^\d+$/.test(timestamp) &&
  Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) <= TOLERANCE_SECONDS;
const expected = Buffer.from(
  crypto
    .createHmac('sha256', $env.LENDLOOP_CONVEX_TO_N8N_SECRET)
    .update(`${timestamp}.${raw}`)
    .digest('hex'),
  'utf8',
);
// Byte lengths, not string lengths: timingSafeEqual throws on buffers of different sizes.
const valid =
  isFresh && given.length === expected.length && crypto.timingSafeEqual(given, expected);

return [{ json: valid ? { valid, event: JSON.parse(raw) } : { valid } }];

// Plain-text email for one loan event. Uses only the fields Convex sent: first name, email,
// tool name, dates and status.
const event = $input.first().json.event;
const { toolName, startDate, endDate } = event.loan;
const dates = startDate === endDate ? startDate : `${startDate} to ${endDate}`;

const lines = {
  'loan.requested': [
    `Someone would like to borrow your ${toolName}`,
    `A neighbour asked to borrow your ${toolName} for ${dates}. Open LendLoop to approve or decline.`,
  ],
  'loan.approved': [
    `Your request for the ${toolName} was approved`,
    `Good news: the owner approved your request for ${dates}. Arrange the pick-up with them.`,
  ],
  'loan.declined': [
    `Your request for the ${toolName} was declined`,
    `The owner declined your request for ${dates}. Other neighbours may have one to lend.`,
  ],
  'loan.autoDeclined': [
    `Your request for the ${toolName} could not be accepted`,
    `The ${toolName} is not available for ${dates}, so your request was closed.`,
  ],
  'loan.cancelled': [
    `A loan of your ${toolName} was cancelled`,
    `The borrower cancelled the loan for ${dates}. The tool is free again for those days.`,
  ],
  'loan.withdrawn': [
    `Your loan of the ${toolName} was cancelled`,
    `The ${toolName} is no longer listed, so the loan for ${dates} was cancelled.`,
  ],
  'loan.returned': [
    `Thanks for returning the ${toolName}`,
    `The owner marked the ${toolName} as returned. Thank you for borrowing responsibly.`,
  ],
};

const [subject, body] = lines[event.type] ?? [
  'LendLoop update',
  'There is news about one of your loans.',
];

return [
  {
    json: {
      eventId: event.eventId,
      to: event.recipient.email,
      subject,
      text: `Hi ${event.recipient.firstName},\n\n${body}\n\n— LendLoop`,
    },
  },
];

// Calls a signed Convex endpoint: HMAC-SHA256 over "timestamp.body" with the n8n-to-Convex
// secret, exactly as packages/contracts/src/integration/signature.ts verifies it. Every attempt is
// signed afresh (a retry must not resend a stale timestamp), and only failures that can heal are
// retried: network errors, 5xx, 408 and 429. Anything else fails the run at once, which hands it to
// the error workflow.
const crypto = require('crypto');

const CONVEX_MAX_TRIES = 3;
const CONVEX_RETRY_WAIT_MS = 2000;
const CONVEX_TIMEOUT_MS = 10000;
const RETRYABLE_STATUSES = [408, 429];

function signForConvex(body) {
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto
    .createHmac('sha256', $env.LENDLOOP_N8N_TO_CONVEX_SECRET)
    .update(`${timestamp}.${body}`)
    .digest('hex');
  return { timestamp, signature };
}

async function postToConvex(helpers, path, payload) {
  const body = JSON.stringify(payload);
  let lastProblem = '';
  for (let attempt = 1; attempt <= CONVEX_MAX_TRIES; attempt += 1) {
    const { timestamp, signature } = signForConvex(body);
    let status = 0;
    let text = '';
    try {
      const response = await helpers.httpRequest({
        method: 'POST',
        url: `${$env.LENDLOOP_CONVEX_SITE_URL}${path}`,
        headers: {
          'content-type': 'application/json',
          'x-lendloop-timestamp': timestamp,
          'x-lendloop-signature': signature,
        },
        body,
        json: false,
        timeout: CONVEX_TIMEOUT_MS,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
      });
      status = response.statusCode;
      text = typeof response.body === 'string' ? response.body : JSON.stringify(response.body);
    } catch (error) {
      lastProblem = `network error (${error.name})`;
    }
    if (status >= 200 && status < 300) {
      return text === '' ? null : JSON.parse(text);
    }
    if (status !== 0) {
      lastProblem = `HTTP ${status}`;
      const canHeal = status >= 500 || RETRYABLE_STATUSES.includes(status);
      if (!canHeal) {
        break;
      }
    }
    if (attempt < CONVEX_MAX_TRIES) {
      await new Promise((resolve) => setTimeout(resolve, CONVEX_RETRY_WAIT_MS * attempt));
    }
  }
  throw new Error(`Convex ${path} failed: ${lastProblem}`);
}

// Generated by n8n/src/build.mjs. Reports "sent" without any error text (it can hold addresses).
for (const [index] of $input.all().entries()) {
  const source = $('Compose email').itemMatching(index).json;
  await postToConvex(this.helpers, '/n8n/notification-acks', {
    eventId: source.eventId,
    status: 'sent',
  });
}
return $input.all();

